sys_script_include.script:
var BaseDataSourceReader = Class.create();
BaseDataSourceReader.prototype = {
    key_column: 'key',
    value_column: 'value',
    data: [],

    initialize: function(applicationScopeName, dataSourceName, key, value) {
        if (key) this.key_column = key;
        if (value) this.value_column = value;
        this.data = this.fetch(applicationScopeName, dataSourceName);
    },

    getData: function() {
        return this.data;
    },

    fetch: function(applicationScopeName, dataSourceName, columns /*, resolver */ ) {
        var data_source_sys_id = this.getDataSourceSysId(applicationScopeName, dataSourceName);
        var data = this.getValues(data_source_sys_id, columns);
        return data;
    },

    getDataSourceSysId: function(applicationScopeName, dataSourceName) {
        var result = '';
        var gr = new GlideRecord("sys_data_source");
        gr.addQuery("sys_package.source", applicationScopeName);
        gr.addQuery("name", dataSourceName);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) result = gr.getValue("sys_id");
        return result;
    },

    // unstated assumption that the attachment is Excel
    getAttachmentSysId: function(dataSourceSysId) {
        var result = "";
        var gr = new GlideRecord("sys_attachment");
        gr.addQuery("table_name", "sys_data_source");
        gr.addQuery("table_sys_id", dataSourceSysId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) result = gr.getValue("sys_id");
        return result;
    },

    // unstated assumpion data source has two columns,
    // key and value, though these names can be overridden
    getValues: function(dataSourceSysId) {
        var data = [];
        var attachment_sys_id = this.getAttachmentSysId(dataSourceSysId);
        var parser = new sn_impex.GlideExcelParser();
        var gsa = new GlideSysAttachment();
        var attachmentStream = gsa.getContentStream(attachment_sys_id);
        parser.parse(attachmentStream);

		// Note the assumption that the header row is being skipped for us.

        // Stop reading when key and value columns are empty.
        // Use JSON stringify to escape the key and value; note that this
        // returns the value enclosed in double quotes. Use slice to remove.
        var i = 0;
        //parser.next();
        while (parser.next()) {
            i++;
            var row = parser.getRow();
            var key = row[this.key_column];
            var value = row[this.value_column];
            if (!key && !value) {
                gs.info("breaking at row " + i);
                break;
            }

            data.push({
                "key": key,
                "value": value
            });

            // data.push({
            //     "key": JSON.stringify(key).slice(1, -1),
            //     "value": JSON.stringify(value).slice(1, -1)
            // });
        }
        return data;
    },

    type: 'BaseDataSourceReader'
};
